static bool Arm(unsigned char*const sites[3],const unsigned char expected[3][5]){
 if(page||threads.count||!original)return false;
 for(unsigned i=0;i<3;++i)if(!sites[i]||expected[i][0]!=0xe8||memcmp(sites[i],expected[i],5))return false;
 unsigned char*island=AllocateNearPages((unsigned __int64)(uintptr_t)sites[0],4096);if(!island)return false;
 // Leaf tail jump preserves the native CALL return and has no stack frame.
 island[0]=0xff;island[1]=0x25;memset(island+2,0,4);const uintptr_t target=(uintptr_t)&Lookup;memcpy(island+6,&target,8);
 code_patch_batch::Edit edits[3]={};
 for(unsigned i=0;i<3;++i){const __int64 delta=(__int64)(uintptr_t)island-(__int64)(uintptr_t)(sites[i]+5);
  if(delta<-2147483647LL-1||delta>2147483647LL){VirtualFree(island,0,MEM_RELEASE);return false;}
  edits[i].address=sites[i];edits[i].size=5;memcpy(edits[i].before,expected[i],5);memcpy(edits[i].after,expected[i],5);const int rel=(int)delta;memcpy(edits[i].after+1,&rel,4);
 }
 DWORD old=0;
 if(!VirtualProtect(island,4096,PAGE_EXECUTE_READ,&old)||!FlushInstructionCache(GetCurrentProcess(),island,14)){VirtualFree(island,0,MEM_RELEASE);return false;}
 bool possible=false;const bool armed=code_patch_batch::Apply(edits,3,&threads,&possible);
 if(possible)page=island;else VirtualFree(island,0,MEM_RELEASE);
 return armed;
}
